d = json.decode(repo.read("services.json"))
svcs = d["services"]
en = []
for s in svcs:
    if s.get("enabled"):
        en.append(s)
en = sorted(en, key = lambda s: s["name"])
total = 0
for s in en:
    total += s["port"]
return {"enabled": [s["name"] for s in en], "sum": total, "all": svcs}
